package main

import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/mark3labs/mcp-go/server"
	mcptools "github.com/mvanhorn/printing-press-library/library/devices/synology-nas-api/internal/mcp"
)

func main() {
	s := server.NewMCPServer(
		"Synology Dsm",
		"1.0.0",
		server.WithToolCapabilities(false),
	)

	mcptools.RegisterTools(s)
	mcptools.RegisterIntentTools(s)

	// Check transport mode via SYNOLOGY_NAS_API_MCP_TRANSPORT env var.
	// "http" starts a Streamable HTTP server (port SYNOLOGY_NAS_API_MCP_PORT, default 8080).
	// Anything else (or unset) falls back to stdio for local / IDE use.
	transport := os.Getenv("SYNOLOGY_NAS_API_MCP_TRANSPORT")
	if transport == "http" {
		addr := os.Getenv("SYNOLOGY_NAS_API_MCP_ADDR")
		if addr == "" {
			port := os.Getenv("SYNOLOGY_NAS_API_MCP_PORT")
			if port == "" {
				port = "8080"
			}
			addr = ":" + port
		}
		httpServer := server.NewStreamableHTTPServer(s)

		// Graceful shutdown on SIGTERM / SIGINT.
		ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGTERM, syscall.SIGINT)
		defer stop()

		go func() {
			<-ctx.Done()
			_ = httpServer.Shutdown(context.Background())
		}()

		fmt.Fprintf(os.Stderr, "synology-nas-api-pp-mcp: HTTP transport listening on %s\n", addr)
		if err := httpServer.Start(addr); err != nil {
			fmt.Fprintf(os.Stderr, "MCP HTTP server error: %v\n", err)
			os.Exit(1)
		}
		return
	}

	// Default: stdio transport (Claude Desktop, local IDE, etc.)
	if err := server.ServeStdio(s); err != nil {
		fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
		os.Exit(1)
	}
}
